async function boot(){assert(!localStorage.getItem('openplay-review-v1'),'Fresh origin required');localStorage.setItem('openplay-review-v1',JSON.stringify(await(await fetch('fixtures/sampler-playing-181-warped-metadata.json')).json()));const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'App');app=window.openPlay;app.engine.init();app.engine.audioMonitor.mutePhysical(true);$('#music-status').textContent='Import the private research MP3';readiness=setInterval(()=>{if(app.state.tracks.some(t=>t.contentHash==='cb2e756d1fa4ce264767a4f6adbaf9e3f69a040db7889d830abdb429cc1a5ac3')){$('#music-run').disabled=false;$('#music-status').textContent='Imported track ready';}},250);}
